params = %{"name" => args.name, "main_color" => args.main_color, "logo" => args.logo, "language_id" => args.language_id}
case ProjectCreator.create(params: params, user: info.context[:conn].assigns[:current_user]) do
  {:ok, project} -> {:ok, %{project: project, errors: nil}}
  {:error, _reason} -> {:ok, %{project: nil, errors: ["unprocessable_entity"]}}
end

params = %{"name" => args.name, "main_color" => args.main_color, "logo" => args.logo, "locked_file_operations" => args.is_file_operations_locked || false}
case ProjectUpdater.update(project: project, params: params, user: ...) do
  {:ok, project} -> {:ok, %{project: project, errors: nil}}

updates = Lint.fix_updates(results, translations_by_id, config, check_filter)
context = Enum.reduce(updates, context, fn {translation, text}, ctx -> ctx |> Context.assign(:translation, translation) |> Context.assign(:text, text) |> TranslationUpdateBuilder.build() end)
fn -> BasePersister.execute(context) end |> Repo.transaction()

translations = Paginated.paginate(translations_query, args, total_entries: total_entries)
revisions = Enum.map(revision_ids, fn revision_id -> Enum.find(revisions, &(&1.id === revision_id)) end)
{:ok, Map.put(Paginated.format(translations), :revisions, revisions)}

params = %{"email" => email, "role" => role, "project_id" => project.id, "assigner_id" => info.context[:conn].assigns[:current_user].id}
case CollaboratorCreator.create(params) do
  {:ok, collaborator} ->
    Hook.outbound(%Hook.Context{event: "create_collaborator", project_id: project.id, ...})
    {:ok, %{collaborator: collaborator, errors: nil}}

case Prompts.completions(prompt, args.text, config) do
  [%{text: text} | _] -> %{result | text: text}
  _ -> %{result | text: "", errors: ["internal_server_error"]}
end

params = %{"prompt_config" => %{"config" => %{"key" => params[:config_key]}, "provider" => params[:provider], "use_platform" => params[:use_platform]}}
changeset = cast(project, params, [:prompt_config])
Multi.new() |> Multi.update(:project, changeset) |> Repo.transaction()

params = %{"machine_translations_config" => %{"config" => %{"key" => params[:config_key]}, "enabled_actions" => params[:enabled_actions], "provider" => params[:provider], "use_platform" => params[:use_platform]}}
changeset = cast(project, params, [:machine_translations_config])
Multi.new() |> Multi.update(:project, changeset) |> Repo.transaction()

case MachineTranslations.translate([%{value: args.text}], source_language && source_language.slug, target_language.slug, project.machine_translations_config) do
  [%{value: text}] -> %{result | text: text}
  {:error, error} when is_atom(error) -> %{result | error: to_string(error)}
  _ -> result
end
